def clean(df):
    category_mapping = {
        "Office Suplies": "Office Supplies",
        "Accesories": "Accessories"
    }
    df['Category'] = df['Category'].replace(category_mapping)
    return df

def answer(df):
    category_sums = df.groupby('Category')['Revenue'].sum().reset_index()
    result = {}
    for row in category_sums:
        category = row['Category']
        total = row['Revenue']
        result[category] = total
    return result
